  "红魔 / 努比亚：应用信息 → 应用的电池用量 → 电池优化 → <b>后台运行：允许</b>（<b>自启动</b>也选允许，开机激活 Shizuku、更新后自动恢复都靠它）": "RedMagic / Nubia: Información de la app → Consumo de batería → Optimización de batería → <b>Ejecución en segundo plano: permitir</b> (permite también el <b>inicio automático</b>: es lo que reactiva Shizuku al arrancar y lo restaura todo tras una actualización)",
