  "小米 / 红米：应用信息 → <b>省电策略：无限制</b>，<b>自启动</b>打开（常见路径，可能因系统版本不同）": "Xiaomi / Redmi: Información de la app → <b>Ahorro de batería: sin restricciones</b>, activa el <b>inicio automático</b> (ruta habitual; puede variar según la versión)",
  "OPPO / 一加 / 真我：应用信息 → 耗电管理 → <b>允许后台行为</b>、<b>允许自启动</b>（常见路径）": "OPPO / OnePlus / Realme: Información de la app → Ahorro de energía → <b>Permitir actividad en segundo plano</b>, <b>Permitir inicio automático</b> (ruta habitual)",
  "vivo / iQOO：设置 → 电池 → 后台耗电管理 → cccodroid <b>允许后台高耗电</b>；i管家里允许<b>自启动</b>（常见路径）": "vivo / iQOO: Ajustes → Batería → Gestión de consumo en segundo plano → permite <b>alto consumo en segundo plano</b> para cccodroid; en iManager permite el <b>inicio automático</b> (ruta habitual)",
  "华为 / 荣耀：设置 → 应用启动管理 → cccodroid 关闭「自动管理」，手动允许<b>自启动</b>和<b>后台活动</b>（常见路径）": "Huawei / Honor: Ajustes → Gestión de inicio de apps → desactiva «Gestionar automáticamente» para cccodroid y permite manualmente el <b>inicio automático</b> y la <b>actividad en segundo plano</b> (ruta habitual)",
  "检测到 cccodroid 在后台被系统冻结过 {n} 次（最近一次约 {sec} 秒，{at}）。": "cccodroid se ha congelado en segundo plano {n} veces (la última durante unos {sec} s, {at}).",
  "冻结期间网关和正在跑的任务全部停住，回到前台才继续。前台服务挡不住这类厂商冻结器。": "Mientras está congelado, la pasarela y las tareas en curso se detienen por completo y solo siguen al volver al primer plano. Un servicio en primer plano no detiene este tipo de congelador del fabricante.",
  "在系统设置里给 cccodroid 允许后台运行、关闭电池优化、允许自启动（各家叫法不同）。": "En los ajustes del sistema, permite la ejecución en segundo plano, desactiva la optimización de batería y permite el inicio automático para cccodroid (los nombres varían según el fabricante).",
  "✓ 已就绪 · 以 {who} 身份执行": "✓ Listo · ejecutando comandos como {who}",
