  "Shizuku 不是由 cccodroid 激活的：重启手机后 cccodroid 没法自动激活它。配对一次即可。": "Shizuku no lo inició cccodroid, así que cccodroid no puede reactivarlo tras reiniciar. Basta con emparejarlo una vez.",
