  "更新开发工具包？\n\n要下多少见这一项旁边标的大小（断点续传），装的时候会暂停服务 1–2 分钟。\n你用 pip / npm -g 装进工具包的东西会被保留。": "¿Actualizar el kit de desarrollo?\n\nEl tamaño de la descarga aparece junto a este elemento (se puede reanudar); al instalar, el servicio se pausa 1–2 minutos.\nLo que hayas instalado en el kit con pip / npm -g se conserva.",
  "开始": "Iniciado",
  "自动更新（默认开）：Claude Code 静默更新；新版应用下载好后提醒安装（有 Shizuku 时空闲自动装）；开发工具包只在 Wi‑Fi 下预先下载，下次打开应用时装上": "Actualización automática (activada por defecto): Claude Code se actualiza en silencio; la nueva versión de la aplicación se descarga y luego te avisa para instalarla (se instala sola cuando está inactiva si hay Shizuku); el kit de desarrollo solo se predescarga con Wi-Fi y se instala la próxima vez que abras la aplicación",
  "开启后台保活增强？\n\n会改几项系统设置：幽灵进程上限（影响所有应用）、本应用的电池白名单与后台运行限制。关掉开关会恢复前两项。": "¿Activar el refuerzo de keep-alive?\n\nCambia algunos ajustes del sistema: el límite de procesos fantasma (afecta a todas las aplicaciones), la lista blanca de batería y los límites de ejecución en segundo plano de esta aplicación. Apagar el interruptor restaura los dos primeros.",
