  "GitHub 已登录，但 git 凭据没配上，可在终端运行 gh auth setup-git": "Sesión iniciada en GitHub, pero no se configuraron las credenciales de git. Ejecuta gh auth setup-git en la terminal",
  "正在向 GitHub 申请一次性码…": "Solicitando un código de un solo uso a GitHub…",
  "在浏览器里输入这个一次性码，授权后这里会自动完成：": "Introduce este código de un solo uso en el navegador. Se completará automáticamente cuando autorices:",
