  "还没登录 GitHub。登录后 gh 和 git 推送都能用。": "No has iniciado sesión en GitHub. Inicia sesión para usar gh y git push.",
  "一次性码过期了，重新登录吧": "El código de un solo uso caducó. Vuelve a iniciar sesión",
