  "Claude 想问你": "Claude tiene una pregunta",
  "需要确认": "Requiere confirmación",
  "说说要怎么改（会发回给 Claude）": "Di qué cambiar (se envía a Claude)",
  "可选：告诉 Claude 为什么 / 该怎么做": "Opcional: dile a Claude por qué / qué hacer en su lugar",
  "发回意见": "Enviar comentario",
  "拒绝": "Denegar",
  "拒绝并停止": "Denegar y detener",
  "先选一个选项，或者写下你的回答": "Elige una opción o escribe tu respuesta",
  "✓ 已批准计划": "✓ Plan aprobado",
  "✓ 已回答": "✓ Respondido",
  "✓ 已允许（始终）": "✓ Permitido (siempre)",
  "✓ 已允许": "✓ Permitido",
  "✗ 已拒绝并停止": "✗ Denegado y detenido",
  "✗ 已拒绝": "✗ Denegado",
  "已撤回": "Retirado",
  "已停止（这一轮结束了）": "Detenido (el turno terminó)",
  "已失效": "Caducado",
  "权限模式已改为「逐项确认」，与官方一致：改文件、跑命令前会先问你。想恢复全部放行，点下方的权限标签。": "El modo de permisos ahora es «Preguntar cada vez», igual que en la versión oficial: Claude pregunta antes de editar archivos o ejecutar comandos. Para volver a permitir todo, toca la etiqueta de permisos de abajo.",
  "Claude 在等你确认": "Claude espera tu confirmación",
  "查看": "Ver",
  "还有 {n} 项": "{n} más",
  "全部允许": "Permitir todo",
  "等你确认…": "Esperando tu confirmación…",
  "读文件不问；改文件、跑命令、联网前先问你": "Lee sin preguntar; pregunta antes de editar archivos, ejecutar comandos o conectarse",
  "改文件不问，跑命令还要问": "Edita sin preguntar; aún pregunta antes de ejecutar comandos",
  "只读和出计划，等你批准再动手": "Solo lectura y planificación; actúa cuando apruebas el plan",
  "由 Claude 的分类器判断哪些要问（实验）": "El clasificador de Claude decide qué preguntar (experimental)",
  "什么都不问。Claude 可以不经你同意删文件、跑任意命令": "Nunca pregunta. Claude puede borrar archivos y ejecutar cualquier comando sin tu permiso",
  "切到「全部放行」？\n\nClaude 将不再询问，可以直接改写、删除文件，运行任意命令，访问网络。只在你信任当前任务、且出了事能承受的时候用。": "¿Cambiar a «Permitir todo»?\n\nClaude dejará de preguntar y podrá editar o borrar archivos, ejecutar cualquier comando y acceder a la red. Úsalo solo si confías en la tarea y puedes asumir las consecuencias.",
  "已切到「{m}」，这一轮当场生效": "Cambiado a «{m}»: se aplica a este turno de inmediato",
  "已切到「{m}」": "Cambiado a «{m}»",
  "切换权限模式": "Cambiar modo de permisos",
  "default · 逐项确认（默认）": "default · preguntar cada vez (predeterminado)",
  "dontAsk · 不询问（要确认的一律拒绝）": "dontAsk · no preguntar (denegar todo lo que requiera confirmación)",
  "bypassPermissions · 全部放行": "bypassPermissions · permitir todo",
  "默认逐项确认，和官方一致：改文件、跑命令前会在对话里问你。全部放行意味着 Claude 不问你就能删文件、跑任意命令。也可以点输入框下方的权限标签随时切换。": "Por defecto pregunta cada vez, como la versión oficial: Claude te pregunta en la conversación antes de editar archivos o ejecutar comandos. «Permitir todo» significa que Claude puede borrar archivos y ejecutar cualquier comando sin preguntar. También puedes cambiarlo cuando quieras con la etiqueta de permisos bajo el cuadro de texto.",
  "↩ 已退回修改": "↩ Devuelto para revisión",
  "在浏览器打开下面的地址完成授权，授权后浏览器跳回本机，登录自动完成：": "Abre el enlace de abajo en el navegador para autorizar. Después el navegador vuelve a este dispositivo y el inicio de sesión se completa solo:",
  "浏览器跳不回来（比如在别的设备上授权）：打开终端运行 {cmd}，把页面给出的授权码直接贴给 claude。": "Si el navegador no puede volver (p. ej. autorizaste en otro dispositivo): abre una terminal, ejecuta {cmd} y pega el código de la página directamente en claude.",
  "浏览器没跳回来（或在别的设备上授权）？在终端里登录：授权码由你直接贴给 claude，本应用不经手。": "¿El navegador no volvió (o autorizaste en otro dispositivo)? Inicia sesión desde una terminal: pegas el código directamente en claude; esta app nunca lo maneja.",
  "在终端里登录": "Iniciar sesión desde una terminal",
  "开发工具": "Herramientas de desarrollo",
