  "Claude 每次调用工具（改文件、跑命令、联网……）之前。退出码 2 会拦下这次调用，stderr 里写的原因会转告 Claude。": "Antes de cada llamada a una herramienta (editar archivos, ejecutar comandos, conectarse…). El código 2 bloquea la llamada y el motivo escrito en stderr se pasa a Claude.",
  "用完工具之后": "Después de usar una herramienta",
  "工具执行成功之后。适合格式化、记录、检查；动作已经做了，退出码 2 只会把 stderr 反馈给 Claude。": "Después de que una herramienta funcione. Útil para formatear, registrar o comprobar; la acción ya ocurrió, así que el código 2 solo devuelve stderr a Claude.",
  "你发出消息时": "Cuando envías un mensaje",
  "你每发一条消息。命令打印的内容会作为补充说明一起交给 Claude；退出码 2 会拦下这条消息。": "Cada vez que envías un mensaje. Lo que imprima el comando se pasa a Claude como contexto; el código 2 bloquea el mensaje.",
  "Claude 答完一轮时": "Cuando Claude termina un turno",
  "Claude 这一轮回答结束。适合自动存档、提醒；退出码 2 会让它接着干（小心死循环）。": "Al terminar la respuesta de Claude. Útil para autoguardado y recordatorios; el código 2 hace que siga (cuidado con los bucles infinitos).",
  "会话开始时": "Al iniciar una sesión",
  "新开、继续、清空或压缩后的会话开始时。命令打印的内容会作为背景交给 Claude。": "Al iniciar una sesión: nueva, reanudada, limpiada o tras compactar. Lo que imprima el comando se da a Claude como contexto.",
  "会话结束时": "Al terminar una sesión",
  "会话结束时，适合收尾清理。": "Al terminar una sesión. Útil para limpiar.",
  "Claude 发提醒时": "Cuando Claude envía un aviso",
  "Claude 要你确认权限、或者闲着等你回复时。": "Cuando Claude necesita un permiso o espera tu respuesta.",
  "要你确认权限时": "Al pedir permiso",
  "弹出权限确认之前。进阶用法：输出 JSON 可以替你自动允许或拒绝。": "Antes de mostrar una solicitud de permiso. Avanzado: imprimir JSON puede permitir o denegar automáticamente.",
  "工具出错之后": "Después de que falle una herramienta",
  "工具执行失败之后。": "Después de que falle una herramienta.",
  "子代理开始时": "Al iniciar un subagente",
  "子代理结束时": "Al terminar un subagente",
  "子代理干完活时；退出码 2 会让它接着干。": "Cuando un subagente termina; el código 2 hace que siga.",
  "压缩上下文之前": "Antes de compactar el contexto",
  "压缩上下文之后": "Después de compactar el contexto",
  "保护重要文件": "Proteger archivos importantes",
  "Claude 想改 .env、密钥、签名文件时直接拦下，并告诉它原因。": "Impide que Claude edite .env, claves y archivos de firma, y le explica por qué.",
  "受保护的文件（一行一个；* 是通配符，带 / 就按路径比）": "Archivos protegidos (uno por línea; * es comodín; con / se compara la ruta completa)",
  "拦下危险命令": "Bloquear comandos peligrosos",
  "命令里出现强推、硬重置、删根目录这类内容就不让跑，并告诉 Claude 换个做法。": "Rechaza comandos como force-push, reset --hard o borrar la raíz, y pide a Claude otra forma.",
  "禁止的内容（一行一个；写成 /…/ 就是正则）": "Texto prohibido (uno por línea; /…/ es una regex)",
  "每轮自动存档（git）": "Autoguardado en cada turno (git)",
  "Claude 每答完一轮，项目里有改动就自动提交一次，随时能退回任意一步。只提交不推送；不是 git 仓库的项目什么也不做。": "Cada vez que Claude termina un turno, los cambios del proyecto se confirman y puedes volver a cualquier paso. Solo hace commit, nunca push; los proyectos sin git no se tocan.",
  "提交说明的开头": "Inicio del mensaje de commit",
  "自动存档": "Autoguardado",
  "每条消息附上固定要求": "Añadir instrucciones fijas a cada mensaje",
  "你每发一条消息，自动把这段话一起交给 Claude，比如「回答用中文」「改之前先说思路」。": "Cada mensaje incluye este texto para Claude, p. ej. «responde en español» o «explica tu plan antes de editar».",
  "要附上的话": "Texto que se añade",
  "回答用中文；动手改之前先简单说一下打算怎么做。": "Responde en español; antes de cambiar nada, explica brevemente qué piensas hacer.",
  "开会话时读入进度文件": "Leer un archivo de progreso al iniciar la sesión",
  "每次开新会话（或压缩上下文后），把项目里的一个文件读给 Claude，比如进度、大纲、人物表。文件不存在就跳过。": "En cada sesión nueva (o tras compactar) se le lee a Claude un archivo del proyecto: progreso, esquema, lista de personajes… Se omite si no existe.",
  "文件（相对项目目录）": "Archivo (relativo a la carpeta del proyecto)",
  "进度.md": "progreso.md",
  "记下 Claude 跑过的命令": "Registrar los comandos que ejecuta Claude",
  "每条命令连同时间、目录追加到 ~/.claude/bash-history.log，方便事后翻看。": "Añade cada comando, con hora y carpeta, a ~/.claude/bash-history.log para revisarlo después.",
  "改完代码自动格式化": "Formatear el código tras editar",
  "Claude 改完代码文件，用本机已装的工具（ruff / black、prettier、gofmt、clang-format……）整理格式；没装就不动。Markdown 和纯文本不碰。": "Tras editar un archivo de código, se formatea con la herramienta instalada (ruff / black, prettier, gofmt, clang-format…); si no hay ninguna, no pasa nada. Markdown y texto plano nunca se tocan.",
  "Hooks（自动规则）": "Hooks (reglas automáticas)",
  "hooks 就是「到了某个时刻，自动跑一条命令」：Claude 用工具之前或之后、你发消息时、它答完一轮时……命令可以拦下 Claude 的动作、给它补充说明，也可以顺手做些杂事（存档、记录、格式化）。": "Un hook es «cuando llegue este momento, ejecuta este comando»: antes o después de que Claude use una herramienta, al enviar un mensaje, al terminar un turno… El comando puede bloquear una acción, darle contexto o hacer tareas (guardar, registrar, formatear).",
  "常用规则（点「添加」，改改参数就能用）": "Reglas comunes (toca Añadir y ajusta)",
  "自己写一条": "Escribir una propia",
  "hooks 是怎么工作的": "Cómo funcionan los hooks",
  "命令在项目目录里用 bash 运行，Claude 会把这一刻的情况（哪个工具、什么参数、你说了什么……）以 JSON 从标准输入传给它。<br>退出码决定结果：<b>0</b> 正常放行；<b>2</b> 拦下这一步（「用工具之前」「你发出消息时」），stderr 里写的原因会转告 Claude；其他退出码算出错，不拦，Claude 照常继续。<br>「你发出消息时」和「会话开始时」的命令打印出来的内容，会作为补充说明交给 Claude。<br>改动在下一条消息生效。规则是普通的 shell 命令，能做的事和你在终端里一样多——别加来路不明的命令。": "El comando se ejecuta con bash en la carpeta del proyecto. Claude le pasa los detalles del momento (qué herramienta, qué argumentos, qué dijiste…) en JSON por la entrada estándar.<br>El código de salida decide: <b>0</b> deja pasar; <b>2</b> bloquea el paso (en «Antes de usar una herramienta» y «Cuando envías un mensaje») y el motivo escrito en stderr se pasa a Claude; cualquier otro código es un error, no se bloquea nada.<br>En «Cuando envías un mensaje» y «Al iniciar una sesión», lo que imprima el comando se da a Claude como contexto.<br>Los cambios se aplican desde el próximo mensaje. Las reglas son comandos de shell normales y pueden hacer lo mismo que tú en una terminal: no añadas comandos de origen dudoso.",
  "耗电": "Batería",
