  "还没有模型。到「扩展」页 llama-cpp 组件下的「下载模型」一键下载，或把 .gguf 文件放进上面的目录。": "Aún no hay modelos. Descarga uno en «Descargar modelos» del componente llama-cpp (página Extensiones) o coloca un archivo .gguf en la carpeta de arriba.",
