  "手机算力有限，小模型干不了活，所以只内置聊天。想自己折腾的话，可以写 {file} 开一个自定义模式（指定工具、系统提示、llama-server 参数）。最省事的办法：切到云端模型，把下面这句发给它：": "Un móvil no tiene potencia para que un modelo pequeño haga trabajo real, así que solo viene el chat. Si quieres experimentar, escribe {file} para activar un modo personalizado (herramientas, indicación del sistema, opciones de llama-server). Lo más fácil: cambia a un modelo en la nube y envíale esto:",
