  "更早的部分是从历史会话补算的（删掉的会话补不回来）。": "Los datos anteriores se reconstruyeron a partir de sesiones pasadas (las sesiones borradas no se recuperan).",
  "只记次数和用量，不记对话内容；数据只存在本机。": "Solo se guardan recuentos y uso, nunca el contenido; los datos se quedan en este dispositivo.",
  "正在从历史会话补算…": "Reconstruyendo desde sesiones pasadas…",
