  "收起二维码": "Ocultar código QR",
  "QQ 交流群二维码": "Código QR del grupo de QQ",
  "用起来有问题、有想法，欢迎进群聊。报 bug 最好走「设置 → 到 GitHub 反馈」，机型和自检结果会自动带上，群里消息一多就沉了。": "¿Dudas o ideas? Pásate a charlar. Para errores, usa Ajustes → Informar en GitHub: el dispositivo y el autodiagnóstico se rellenan solos y el informe no se pierde en el chat.",
  "这个项目目前只有作者一个人在维护，非常需要帮手：译文校对、机型适配报告、组件配方、文档、代码都欢迎，不会写代码也能帮上忙。怎么参与见仓库里的贡献指南。": "cccodroid lo mantiene una sola persona y necesita ayuda: correcciones de traducción, informes de dispositivos, recetas de componentes, documentación y código son bienvenidos, y puedes ayudar sin programar. La guía de contribución del repositorio explica cómo.",
  "讨论区": "Debates",
  "反馈问题": "Informar de un problema",
