  "这个组件只能用在 ARM Mali GPU（天玑、Exynos 等）的设备上，本机用不了": "Este componente solo funciona en dispositivos con GPU ARM Mali (Dimensity, Exynos, etc.); aquí no se puede usar",
  "只限 ARM Mali GPU（天玑、Exynos 等）设备，本机用不了": "Solo GPU ARM Mali (Dimensity, Exynos…); aquí no funciona",
  "Mali 专用": "Solo Mali",
  "设备工具": "Herramientas del dispositivo",
  "让 Claude 使用设备工具（通知、剪贴板、打开链接 / 日历 / 闹钟、分享文件…）": "Permitir que Claude use las herramientas del dispositivo (notificaciones, portapapeles, abrir enlaces / calendario / alarmas, compartir archivos…)",
  "调用时和其他工具一样，按你选的权限模式确认。会打开别的应用的只是预填，保存、发送、拨出都由你在那个应用里点。": "Las llamadas se confirman como las de cualquier otra herramienta, según tu modo de permisos. Lo que abre otra app solo rellena los datos: guardar, enviar o llamar lo pulsas tú en esa app.",
  "读屏与点按（无障碍）": "Lectura de pantalla y toques (accesibilidad)",
  "关（默认）": "Desactivado (predeterminado)",
  "用时自动开，空闲后自动关（要先激活 Shizuku）": "Se activa al usarlo y se apaga tras inactividad (requiere Shizuku activado)",
  "常开（较耗电）": "Siempre activado (consume más batería)",
  "空闲多久自动关（分钟）": "Apagar tras inactividad (minutos)",
  "去系统无障碍设置": "Abrir ajustes de accesibilidad del sistema",
  "无障碍服务：已连接": "Servicio de accesibilidad: conectado",
  "无障碍服务：关": "Servicio de accesibilidad: desactivado",
  "无障碍服务：现在没开（用到时再开）": "Servicio de accesibilidad: apagado por ahora (se activa al usarlo)",
  "还没激活 Shizuku，应用没法自己开关无障碍：去系统无障碍设置里手动打开 cccodroid。安卓 13 起，侧载的应用要先在 应用信息 → 右上角菜单 → 允许受限设置。": "Shizuku no está activado, así que la app no puede encender el servicio de accesibilidad por sí misma: actívala en los ajustes de accesibilidad del sistema. Desde Android 13, las apps instaladas fuera de la tienda necesitan antes Info de la app → menú arriba a la derecha → Permitir ajustes restringidos.",
  "设备状态": "Estado del dispositivo",
