  "来源：Termux 官方仓库 · 快照 {s}": "Origen: repositorios oficiales de Termux · instantánea {s}",
  "安装（约 {a}）": "Instalar (unos {a})",
  "{names} 要用它，先卸载那些": "{names} lo necesitan; desinstálalos primero",
  "卸载这个模块？它的命令会从工具包里删掉，别的模块和组件还在用的文件会留下。以后可以随时再装。": "¿Desinstalar este módulo? Sus comandos se quitan del kit de herramientas; se conservan los archivos que aún usan otros módulos o componentes. Puedes volver a instalarlo cuando quieras.",
  "会一起装上：{list}。继续？": "También se instalará: {list}. ¿Continuar?",
  "要先装工具包模块：{names}（扩展页上方「工具包模块」）": "Primero instala estos módulos del kit: {names} (en «Módulos del kit de herramientas», arriba en Extensiones)",
  "没有这个模块：{id}": "No existe el módulo: {id}",
  "当前是整包工具包，没有模块可装": "El kit de herramientas actual es de un solo bloque; no hay módulos que instalar",
  "另一个模块正在装，等它结束再试": "Se está instalando otro módulo; vuelve a intentarlo cuando termine",
  "工具包是从本地文件装的，不知道该去哪个 Release 下载模块。请先在设置里更新一次工具包": "El kit se instaló desde un archivo local, así que no se sabe de qué versión descargar los módulos. Actualízalo primero una vez en Ajustes",
  "存储空间不够：需要约 {need} MB，只剩 {free} MB": "No hay espacio suficiente: se necesitan unos {need} MB y solo quedan {free} MB",
  "模块包缺文件：{file}": "Falta un archivo en el paquete del módulo: {file}",
  "模块包里的文件校验不符：{file}": "Un archivo del paquete del módulo no superó la verificación: {file}",
  "当前是整包工具包，没有模块可卸": "El kit de herramientas actual es de un solo bloque; no hay módulos que desinstalar",
  "基础模块不能卸载": "El módulo base no se puede desinstalar",
  "共享运行库跟着用它的模块走，不能单独卸载": "Las bibliotecas compartidas van con los módulos que las usan y no se pueden desinstalar por separado",
  "有模块正在安装，等它结束再试": "Se está instalando un módulo; vuelve a intentarlo cuando termine",
  "工具包模块": "Módulos del kit de herramientas",
  "开发工具包按用途拆成模块，用得上的才装。基础模块必装；共享运行库跟着用它的模块自动装卸。": "El kit de desarrollo está dividido en módulos según su uso: instala solo lo que necesites. El módulo base es obligatorio; las bibliotecas compartidas se instalan y quitan solas con los módulos que las usan.",
  "主要命令：": "Comandos principales:",
  "待发 {n} 条 · 这个会话的上一轮还没完全结束（后台任务在跑或正在收尾），结束后依次发出": "{n} en espera · el turno anterior de esta conversación aún no ha terminado del todo (tareas en segundo plano o cierre); se enviarán cuando termine",
  "已排队：这个会话的上一轮还没完全结束，结束后发出": "En cola: el turno anterior de esta conversación aún no ha terminado del todo; se enviará cuando termine",
  "卸载开发工具包？\n\n会删掉整个工具包，连同装在里面的组件、加装的模块、你用 pip / npm -g / pkg 装的东西，然后回到首次安装，重新选下载来源和模块。\n\n会话、工作区、登录和设置都保留。正在跑的终端会被关掉。": "¿Desinstalar el kit de desarrollo?\n\nSe borra el kit completo, junto con los componentes instalados en él, los módulos añadidos y todo lo que hayas instalado con pip / npm -g / pkg; después vuelve la instalación inicial para elegir de nuevo el origen de descarga y los módulos.\n\nSe conservan las conversaciones, el espacio de trabajo, la sesión iniciada y los ajustes. Los terminales abiertos se cerrarán.",
  "卸载 Claude Code？\n\n删掉已下载的 Claude Code 程序，之后不会自动装回。要用时在这里点「安装…」，自己选版本（stable、latest 或具体版本号）。\n\n登录、会话和设置都保留；没装的时候发消息会提示先安装。": "¿Desinstalar Claude Code?\n\nSe borra el programa Claude Code descargado y no se reinstalará automáticamente. Cuando lo necesites, toca «Instalar…» aquí y elige la versión (stable, latest o un número concreto).\n\nSe conservan la sesión iniciada, las conversaciones y los ajustes; si envías un mensaje sin tenerlo, se te pedirá instalarlo primero.",
  "旧工具包留下的 {n} 个程序（{size}）已隔离，{d} 天后自动删除。": "{n} programas que dejó el kit anterior ({size}) están en cuarentena y se borrarán automáticamente en {d} días.",
  "立即删除": "Borrar ahora",
  "立即删除隔离的 {n} 个旧程序？删了就找不回来了。": "¿Borrar ahora los {n} programas antiguos en cuarentena? No se puede deshacer.",
  "已删除 {n} 个": "{n} borrados",
  "安装…": "Instalar…",
  "装哪个版本？\n填 stable、latest，或具体版本号（如 {v}）。": "¿Qué versión instalar?\nEscribe stable, latest o un número de versión concreto (p. ej. {v}).",
  "Claude Code 未安装。到 设置 → 更新 里点「安装…」选一个版本装上。": "Claude Code no está instalado. Ve a Ajustes → Actualizaciones y toca «Instalar…» para elegir una versión.",
  "CLI：固定 {v}": "CLI: fijada {v}",
  "CLI：固定版本…": "CLI: fijar una versión…",
