  "模块「{name}」上次没装完": "El módulo «{name}» no terminó de instalarse la última vez",
  "到 扩展 → 工具包模块 重新安装": "Reinstálalo en Extensiones → Módulos del kit de herramientas",
  "模块「{name}」缺文件列表（FILES），卸载时会删不干净": "El módulo «{name}» no tiene lista de archivos (FILES); al desinstalarlo quedarían restos",
  "模块「{name}」少了 {n} 个文件（共 {total} 个）": "Faltan {n} de los {total} archivos del módulo «{name}»",
  "自定义组件「{id}」的记录读不出来": "No se puede leer el registro del componente personalizado «{id}»",
  "到 扩展 → 自定义组件 删掉重新导入": "Elimínalo en Extensiones → Componentes personalizados e impórtalo de nuevo",
  "自定义组件「{id}」的程序或库不在了": "Han desaparecido el programa o las bibliotecas del componente personalizado «{id}»",
  "核对记录": "Comprobar registros",
  "这个会话还没存下来，答完一轮再删": "Esta sesión aún no se ha guardado. Borra después de una respuesta completa",
  "正在生成，等它答完再删": "Generando. Espera a que termine para borrar",
  "这条回复前面没有你的消息，没法单独删": "No hay un mensaje tuyo antes de esta respuesta, así que no se puede borrar sola",
  "删掉这条提问？Claude 之后就看不到它了（它的回复保留）。": "¿Borrar este mensaje? Claude ya no lo verá (su respuesta se queda).",
  "删掉这条回复？连同它的工具调用和结果一起删，Claude 之后就看不到了。": "¿Borrar esta respuesta? Sus llamadas a herramientas y resultados se van con ella, y Claude ya no los verá.",
  "回车直接发送": "Intro envía",
  "回车换行，Ctrl + 回车或点发送键发出": "Intro añade una línea. Ctrl + Intro o el botón de enviar envía",
