  "开关": "Activar/desactivar",
  "到点在本机跑一次 Claude，在指定目录里；跑完按设置通知你，结果存成一个对话。没人在旁边：要问你的操作一律当拒绝。错过的不会偷偷补跑，按每个任务的设置来。": "A la hora fijada, Claude se ejecuta una vez en este dispositivo en la carpeta elegida; te avisa según el ajuste y el resultado se guarda como conversación. Nadie está mirando: cualquier acción que necesite tu aprobación se rechaza. Las ejecuciones perdidas nunca se recuperan a escondidas; decide el ajuste de cada tarea.",
  "开着的": "Activadas",
