  "到上限后当天其余任务跳过，并通知你。第三方接口多数不回报花费，按 0 记。": "Al llegar al límite se omiten las tareas restantes del día y se te avisa. La mayoría de las API de terceros no informan del coste, así que cuenta como 0.",
  "改上限": "Cambiar límite",
