  "计时在网关里：App 开着或在后台运行时到点就跑；被系统清掉、关机时会错过，下次打开按任务的「错过了」设置处理。": "El temporizador está en la pasarela: las tareas se ejecutan a su hora mientras la app esté abierta o en segundo plano. Si el sistema la cierra o el dispositivo está apagado, la ejecución se pierde y se trata según el ajuste «Si se pierde» la próxima vez que abras la app.",
