  "想「没事就别吵我」：让它没发现时只回一句固定的话（比如「全绿」），下面的通知选「只在有发现时」。": "¿Quieres «no me molestes si no pasa nada»? Pídele que responda una frase fija cuando no encuentre nada (p. ej. «Todo en verde») y elige abajo «Solo si encuentra algo».",
