  "原生、「求索」或「逐月」配色": "Colores nativos, Qiusuo o Zhuyue",
  "只改这个会话，从下一条消息起生效；没单独选过的会话跟着设置里的默认走。": "Solo cambia esta sesión, a partir del siguiente mensaje; las sesiones sin elección propia siguen el valor predeterminado de Ajustes.",
  "改回跟随默认": "Volver a seguir el predeterminado",
  "跟随默认：{model}": "Sigue el predeterminado: {model}",
  "点一个模型，这个会话就换到「{name}」": "Toca un modelo para pasar esta sesión a «{name}»",
  "这个会话改用「{name}」，下一条消息起生效": "Esta sesión usa ahora «{name}», a partir del siguiente mensaje",
  "这个会话改用「{name}」接着聊？\n\n之前的对话会整段交给新接口的模型重新读：提示缓存从头算，费用按新接口计；个别工具调用记录别家模型可能读不懂。": "¿Seguir esta sesión con «{name}»?\n\nToda la conversación la volverá a leer el modelo del nuevo proveedor: la caché del prompt empieza de cero y se factura según el nuevo proveedor. Algunos registros de herramientas pueden no entenderse en el modelo de otro proveedor.",
  "执行方式": "Modo de ejecución",
  "自动：按安装包定。直接执行：工具包里的程序直接运行（targetSdk 28 的安装包）。经加载器：借系统加载器间接运行，targetSdk 36 的安装包只能这样；28 的也能选，用来排查问题。改完重启网关才生效。": "Auto: lo decide el paquete instalado. Directo: los programas del kit se ejecutan directamente (paquete targetSdk 28). Mediante cargador: se inician a través del cargador del sistema; es la única forma en un paquete targetSdk 36, y el 28 también puede elegirlo para diagnosticar. Se aplica al reiniciar la pasarela.",
  "直接执行": "Directo",
  "经加载器": "Mediante cargador",
  "现在是：{mode}": "Ahora: {mode}",
  "执行方式已保存。现在重启网关让它生效吗？打开的终端会断开。": "Modo de ejecución guardado. ¿Reiniciar la pasarela ahora para aplicarlo? Los terminales abiertos se desconectarán.",
  "网关重启中…": "Reiniciando la pasarela…",
  "这个版本（targetSdk {n}）只能经加载器运行，不能切到直接执行": "Esta versión (targetSdk {n}) solo funciona mediante el cargador; no puede cambiar a ejecución directa",
  "还有任务在跑，等它们结束再重启": "Aún hay tareas en curso; reinicia cuando terminen",
  "安装包里的 glibc 加载器和工具包里的不是同一版，经加载器暂时用不了：先更新工具包": "El cargador glibc del paquete no es la misma versión que el del kit; por ahora no se puede usar «mediante cargador»: actualiza primero el kit",
  "安装包方案": "Paquete de instalación",
  "targetSdk 28 是默认的那套，兼容性最好；targetSdk 36 给系统不让装 28 的新机器用。两套功能一样，数据通用，互相覆盖安装不丢东西。自动：跟着现在装的走，系统拒装 28 时自动换成 36。": "targetSdk 28 es el paquete predeterminado y el más compatible; targetSdk 36 es para equipos nuevos cuyo sistema no permite instalar 28. Ambos funcionan igual y comparten datos, así que instalar uno sobre otro no pierde nada. Auto: sigue con el instalado y cambia a 36 si el sistema rechaza 28.",
  "现在装的是 targetSdk {n}": "Instalado ahora: targetSdk {n}",
  "下次更新换成 targetSdk {n}": "La próxima actualización cambia a targetSdk {n}",
  "系统已不让装 targetSdk 28，只能用 36": "El sistema ya no permite targetSdk 28; aquí solo funciona 36",
  "换成 targetSdk {n} 的安装包？\n\n会下载同一版本的另一套安装包（约 14 MB）覆盖安装，对话、设置、工具包都保留。安装时应用会重启一次。": "¿Cambiar al paquete targetSdk {n}?\n\nSe descargará el otro paquete de la misma versión (unos 14 MB) y se instalará encima. Se conservan conversaciones, ajustes y el kit de herramientas. La app se reinicia una vez durante la instalación.",
  "有 {n} 项可更新": "{n} actualización(es) disponible(s)",
