  "这个文件夹里没有 SKILL.md（可能是以前导入到一半失败留下的），可以删掉。": "Esta carpeta no tiene SKILL.md (quizá quede de una importación fallida); puedes eliminarla.",
  "这个表格文件内部展开后太大，不能安全打开。": "Esta hoja de cálculo se expande demasiado internamente para abrirla con seguridad.",
  "这张表的范围信息坏了，读不出来": "La información de rango de esta hoja está dañada y no se puede leer",
  "这类系统伪文件不能这样读": "Los pseudoarchivos del sistema como este no se pueden leer así",
  "项目指令还没保存，返回会丢掉这次修改。确定返回？": "Las instrucciones del proyecto no están guardadas; volver descartará estos cambios. ¿Volver de todos modos?",
  "预览服务没有返回地址": "El servicio de vista previa no devolvió una dirección",
  "帮助加载失败：{msg}": "No se pudo cargar la ayuda: {msg}",
  "更新日志加载失败：{msg}": "No se pudo cargar el registro de cambios: {msg}",
  "技能包超过 64 MB，请解压后逐个导入": "El paquete de habilidades supera los 64 MB; descomprímelo e importa las habilidades una por una",
